import { Scene, ThreeDAxes, RaymarchPlot3D, RaymarchStyle, RaymarchColorMode, Color } from "retiam";

const scene = new Scene({ canvas });

const axes = new ThreeDAxes({
    xRange: [-4, 4, 1],
    yRange: [-3, 3, 1],
    zRange: [-4, 4, 1]
});
scene.add(axes);

// 3D Raymarched Sinc ripple function: f(x, z) = 2.0 * sin(r) / r
const surface = new RaymarchPlot3D(axes, {
    userFunctions: `
        fn surfaceFunc(x: f32, z: f32) -> f32 {
            let r = sqrt(x * x + z * z) + 0.0001;
            return 2.0 * sin(r) / r;
        }
    `,
    viewStyle: RaymarchStyle.TOPOGRAPHIC,
    colorMode: RaymarchColorMode.RADIAL,
    showContour: true,
    showGrid: true
});
scene.add(surface);
